local GA = require(game.ReplicatedStorage.GameAssets)
local keys = {}
for k,v in pairs(GA) do table.insert(keys, k..":"..type(v)) end
local CS = require(game.ServerScriptService.CashInService)
local ck = {}
for k,v in pairs(CS) do table.insert(ck, k..":"..type(v)) end
return table.concat(keys, ",") .. " | " .. table.concat(ck, ",")

local src = game.ServerScriptService.CashInService.Source
local i = string.find(src, 'Burst at the intake', 1, true)
return string.sub(src, i or 1, (i or 1)+2500)

local p=game.Players.LocalPlayer
local b=p.PlayerGui.RebirthGui:FindFirstChild("RebirthButton")
local ls=p.leaderstats
local t={}
for _,c in ls:GetChildren() do t[c.Name]=c.Value end
return game:GetService("HttpService"):JSONEncode({btn=b.Text,ls=t,cash=ls.Cash.Value,attrs=p:GetAttributes()})
